python3 - <<'EOF'
import os, stat, tempfile
for d in ['/tmp','/app','/app/submit','/app/tmp','/var/tmp','/dev/shm']:
    try:
        st = os.stat(d)
        print(d, oct(st.st_mode), 'writable' if os.access(d, os.W_OK) else 'NOT writable')
    except Exception as e:
        print(d, 'ERR', e)
print('tempdir', tempfile.gettempdir())
EOF
